            new Quote { Id = "https://ar.wikiquote.org/wiki/إميل_حبيبي", Text = "أوقعتني الشجاعة في مأزق لم أنجو منه إلا بمزيد من هذه الشجاعة.", Author = "إميل حبيبي" },
